// Clasificación por reglas (determinística, explicable, sin costo).
// Puntaje = interés + disponibilidad + canal  →  Caliente / Tibio / Frío
//
// NOTA: el Form Trigger de n8n v2 expone los datos usando el fieldLabel
// como clave (ej. "¿Qué tanto te interesa el evento?").
// Se normaliza aquí a claves cortas antes de puntuar.
const raw = $json;

// Mapa field-N (posícional) → clave corta
// El Form Trigger v2.3+ expone los datos con claves field-0, field-1...
// en el orden en que se definieron los campos en el formulario.
const MAP = {
  'field-0': 'nombre',
  'field-1': 'email',
  'field-2': 'telefono',
  'field-3': 'interes',
  'field-4': 'disponibilidad',
  'field-5': 'canal',
};

const d = {};
for (const [k, v] of Object.entries(raw)) {
  const shortKey = MAP[k] ?? k;
  d[shortKey] = v;
}

const PESOS = {
  interes:        { 'Alto': 40, 'Medio': 20, 'Bajo': 5 },
  disponibilidad: { 'Sí': 40, 'Tal vez': 15, 'No': 0 },
  canal:          { 'Referido': 20, 'WhatsApp': 15, 'Formulario web': 10, 'Redes sociales': 5 },
};

const p = (campo) => PESOS[campo]?.[d[campo]] ?? 0;

const puntaje = p('interes') + p('disponibilidad') + p('canal');
const clasificacion = puntaje >= 70 ? 'Caliente' : puntaje >= 40 ? 'Tibio' : 'Frío';

return {
  json: {
    nombre: String(d.nombre ?? '').trim(),
    email: String(d.email ?? '').trim().toLowerCase(),
    telefono: String(d.telefono ?? '').trim() || null,
    interes: d.interes,
    disponibilidad: d.disponibilidad,
    canal: d.canal,
    puntaje,
    clasificacion,
  },
};

// Arma el correo de seguimiento según la clasificación del lead.
// El botón apunta al webhook del flujo 02 con el token opaco del lead.
const BASE_URL = 'http://localhost:5678';
const lead = $json;
const enlace = `${BASE_URL}/webhook/confirmar?token=${lead.token}`;
const nombre = lead.nombre.split(' ')[0];

const boton = `
  <p style="margin:28px 0">
    <a href="${enlace}" style="background:#6d28d9;color:#fff;padding:14px 26px;
       border-radius:8px;text-decoration:none;font-weight:bold">Confirmo mi asistencia</a>
  </p>`;

const plantillas = {
  'Caliente': {
    asunto: `${nombre}, tu lugar en el evento está reservado 🎟️`,
    cuerpo: `<p>¡Gracias por registrarte! Vimos que tienes alto interés y disponibilidad.</p>
             <p>Solo falta un paso: confirma tu asistencia para asegurar tu cupo.</p>${boton}`,
  },
  'Tibio': {
    asunto: `${nombre}, esto es lo que vivirás en nuestro evento`,
    cuerpo: `<p>Gracias por tu interés. Te contamos más: agenda, ponentes y beneficios
             de asistir en persona.</p>
             <p>Si ya te animaste, confirma aquí y te guardamos un lugar.</p>${boton}`,
  },
  'Frío': {
    asunto: `${nombre}, gracias por tu interés`,
    cuerpo: `<p>Gracias por registrarte. Te iremos enviando contenido útil y novedades
             de próximos eventos, sin compromiso.</p>`,
  },
};

const t = plantillas[lead.clasificacion];
const html = `<div style="font-family:Arial,sans-serif;max-width:560px;color:#1f2937">
  <h2 style="color:#6d28d9">Renaser Eventos</h2>
  <p>Hola ${nombre},</p>${t.cuerpo}
  <hr style="border:none;border-top:1px solid #e5e7eb">
  <small style="color:#6b7280">Clasificación interna: ${lead.clasificacion} (${lead.puntaje} pts)</small>
</div>`;

return { json: { ...lead, asunto: t.asunto, html } };
